17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
29	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
30	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
31	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.util.StringUtils;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
66	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
67	     * addresses are lower-cased before being stored.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
122	        owner.setEmail(normalizeEmail(owner.getEmail()));
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
127	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
128	        }
129	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
130	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
131	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
132	        }
133	        owner.setCustomerCode(buildCustomerCode(owner.getLastName()));
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    /**
142	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
143	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
144	     * so the client receives a 400 whose {@code errors} array lists each missing field.
145	     *
146	     * @param ownerFieldsDto the submitted owner fields
147	     */
148	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
149	        List<String> missingFields = new ArrayList<>();
150	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
151	            missingFields.add("firstName");
152	        }
153	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
154	            missingFields.add("lastName");
155	        }
156	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
157	            missingFields.add("address");
158	        }
159	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
160	            missingFields.add("city");
161	        }
162	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
163	            missingFields.add("telephone");
164	        }
165	        if (!missingFields.isEmpty()) {
166	            throw new MissingOwnerFieldsException(missingFields);
167	        }
168	    }
169	
170	    /**
171	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
172	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
173	     * address; the accepted value is lower-cased before it is stored and returned.
174	     *
175	     * @param email the raw email value submitted by the client, or {@code null}
176	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
177	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
178	     */
179	    private String normalizeEmail(String email) {
180	        if (!StringUtils.hasText(email)) {
181	            return email;
182	        }
183	        if (!EMAIL_PATTERN.matcher(email).matches()) {
184	            throw new InvalidOwnerFieldsException(List.of("email"));
185	        }
186	        return email.toLowerCase();
187	    }
188	
189	    /**
190	     * Builds the owner's customer code formatted {@code <LAST3>-<NNNN>}, where LAST3 is the
191	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
192	     * sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
193	     *
194	     * @param lastName the owner's last name
195	     * @return the assigned customer code
196	     */
197	    private String buildCustomerCode(String lastName) {
198	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
199	        int sequence = this.clinicService.findAllOwners().size() + 1;
200	        return String.format("%s-%04d", last3, sequence);
201	    }
202	
203	    /**
204	     * Determines whether an existing owner already shares a household with the supplied last name and
205	     * address. Two owners belong to the same household when their last names match and their addresses
206	     * match, both compared case-insensitively after collapsing runs of whitespace to a single space
207	     * and trimming, so trivial differences in spacing or letter case still count as a match.
208	     *
209	     * @param lastName the submitted owner's last name
210	     * @param address the submitted owner's address
211	     * @return {@code true} if another owner already has the same normalized last name and address
212	     */
213	    private boolean isDuplicateHousehold(String lastName, String address) {
214	        String normalizedLastName = normalizeForHousehold(lastName);
215	        String normalizedAddress = normalizeForHousehold(address);
216	        return this.clinicService.findAllOwners().stream()
217	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
218	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
219	    }
220	
221	    /**
222	     * Normalizes a value for household duplicate comparison: leading and trailing whitespace is
223	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
224	     * lower-cased so the comparison is case-insensitive.
225	     *
226	     * @param value the raw last name or address value, or {@code null}
227	     * @return the normalized value, or the empty string when {@code value} is {@code null}
228	     */
229	    private String normalizeForHousehold(String value) {
230	        if (value == null) {
231	            return "";
232	        }
233	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
239	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
240	        if (currentOwner == null) {
241	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	        }
243	        currentOwner.setAddress(ownerFieldsDto.getAddress());
244	        currentOwner.setCity(ownerFieldsDto.getCity());
245	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
246	        currentOwner.setLastName(ownerFieldsDto.getLastName());
247	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
248	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
249	        this.clinicService.saveOwner(currentOwner);
250	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Transactional
255	    @Override
256	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        this.clinicService.deleteOwner(owner);
262	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        HttpHeaders headers = new HttpHeaders();
273	        Pet pet = petMapper.toPet(petFieldsDto);
274	        owner.setId(ownerId);
275	        pet.setOwner(owner);
276	        pet.getType().setName(null);
277	        this.clinicService.savePet(pet);
278	        PetDto petDto = petMapper.toPetDto(pet);
279	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
280	            .buildAndExpand(pet.getId()).toUri());
281	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
287	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
288	        if (currentOwner != null) {
289	            Pet currentPet = this.clinicService.findPetById(petId);
290	            if (currentPet != null) {
291	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
292	                currentPet.setName(petFieldsDto.getName());
293	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
294	                this.clinicService.savePet(currentPet);
295	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
296	            }
297	        }
298	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	    }
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
304	        HttpHeaders headers = new HttpHeaders();
305	        Visit visit = visitMapper.toVisit(visitFieldsDto);
306	        Pet pet = new Pet();
307	        pet.setId(petId);
